// throwaway driver: same isolation logic as /tmp/probe/p.mjs but uses --k=value
// so values beginning with '-' survive argparse.
import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
const MK = { a:'MKAA', b:'MKBB', c:'MKCC', d:'MKDD', e:'MKEE', f:'MKFF' };
const ORDER = ['a','b','c','d','e','f'];
export function run(args) {
  const argv = ORDER.map(k => '--' + k + '=' + (args[k] === undefined ? MK[k] : args[k]));
  try { return execFileSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 }); }
  catch (e) { return 'ERR(' + e.status + ')\n' + (e.stdout || '') + (e.stderr || ''); }
}
export function phase(slot, s) {
  const args = { ...MK }; args[slot] = s;
  const out = run(args);
  const lines = out.split('\n');
  const pos = ORDER.indexOf(slot);
  let start = 0;
  for (let k = 0; k < pos; k++) start = lines.indexOf('<p>' + MK[ORDER[k]] + '</p>', start) + 1;
  const end = pos < 5 ? lines.indexOf('<p>' + MK[ORDER[pos + 1]] + '</p>', start)
                      : lines.indexOf('<h1>Combined Document</h1>', start);
  return lines.slice(start, end).join('\n');
}
export function batch(cases, slot='a') {
  const outs = [];
  for (const s of cases) outs.push([s, phase(slot, s)]);
  return outs;
}
export function report(cases, slot='a') {
  for (const s of cases) {
    console.log('IN=' + JSON.stringify(s));
    console.log('OUT=' + JSON.stringify(phase(slot, s)));
    console.log('');
  }
}
EOF
